CREATE TABLE `models` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '模型ID',
  `user_id` int NOT NULL COMMENT '用户ID',
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模型名称',
  `algorithm_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '算法类型',
  `framework` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT 'PyTorch' COMMENT '深度学习框架',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT '模型描述',
  `hyperparameters` text COLLATE utf8mb4_unicode_ci COMMENT '超参数 JSON字符串',
  `architecture` text COLLATE utf8mb4_unicode_ci COMMENT '网络架构 JSON字符串',
  `input_shape` text COLLATE utf8mb4_unicode_ci COMMENT '输入形状 JSON字符串',
  `output_shape` text COLLATE utf8mb4_unicode_ci COMMENT '输出形状 JSON字符串',
  `metrics` text COLLATE utf8mb4_unicode_ci COMMENT '评估指标 JSON字符串',
  `trained_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '训练完成时间',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'completed' COMMENT '状态: pending, training, completed, failed',
  `model_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '模型文件路径',
  `checkpoint_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '检查点路径',
  `model_size` int DEFAULT NULL COMMENT '模型大小（字节）',
  `is_active` tinyint(1) DEFAULT '1' COMMENT '是否激活',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_algorithm_type` (`algorithm_type`),
  KEY `idx_framework` (`framework`),
  KEY `idx_status` (`status`),
  KEY `idx_is_active` (`is_active`),
  KEY `idx_trained_at` (`trained_at`),
  CONSTRAINT `models_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=78 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='模型表';
